import { defineComponent, PropType } from 'vue';

import { SessionData } from '@game-studio/server-comms';
import { OrientationValue } from '@game-studio/device';

import { CurrencyFormatter, SessionInitialData, SessionDataStrings, SessionModel, ServerSessionResponse } from '../../../types';

// UK: Remote Technical Standard
// https://www.gamblingcommission.gov.uk/licensees-and-businesses/guide/remote-gambling-and-software-technical-standards

export type ComponentData = {
    sessionModel: SessionModel;
    displayedBalance: number;
    inActivityResetEnabled: boolean;
    sessionTimeStart: number;
    localActivityTime: number;
    clockTickInterval: number;
    inActiveTimeOutLimit: number;
    sessionTimeLabel: HTMLElement;
    sessionBalanceLabel: HTMLElement;
};

const msPerSecond = 1000;
const secondsPerMinute = 60;
const secondsPerDay = 86400;
const secondsPerHour = 3600;
const fifteenMinutes = 15 * secondsPerMinute;
const labelJustifications = {
    default: 'space-between',
    mid: 'space-around',
    centre: 'center'
} as const;

export default defineComponent({
    name: 'SessionDataVue',
    props: {
        onGameBegin: { type: Function, required: true },
        onGameComplete: { type: Function, required: true },
        onJackpot: { type: Function, required: true },
        labelJustification: { type: Object, default: () => ({ portrait: 'default', landscape: 'default' }) },
        formatCurrency: { type: Function as PropType<CurrencyFormatter>, required: true },
        strings: { type: Object as PropType<SessionDataStrings>, required: true },
        initialData: { type: Object as PropType<SessionInitialData>, required: true },
        displayName: { type: String, default: '' }
    },
    data(): ComponentData {
        return {
            sessionModel: {
                totalSpend: this.initialData.totalSpend,
                gameStart: { ...this.initialData.sessionData },
                gameEnd: { ...this.initialData.sessionData }
            },
            
            displayedBalance: 0,
            inActivityResetEnabled: true,
            sessionTimeStart: -1,
            localActivityTime: -1,
            clockTickInterval: -1,
            inActiveTimeOutLimit: fifteenMinutes,

            sessionTimeLabel: {} as HTMLElement,
            sessionBalanceLabel: {} as HTMLElement
        };
    },
    mounted(): void {
        const sessionDiv = document.getElementById('session-data');
        if (sessionDiv) {
            sessionDiv.style.justifyContent = labelJustifications[this.labelJustification['landscape'] as keyof typeof labelJustifications];
        } else {
            throw new Error('No element matching id session-data found');
        }

        const sessionTimeLabel = document.getElementById('session-time');
        if (sessionTimeLabel) {
            this.sessionTimeLabel = sessionTimeLabel;
        } else {
            throw new Error('No element matching id session-time found');
        }
        
        const sessionBalanceLabel = document.getElementById('session-balance');
        if (sessionBalanceLabel) {
            this.sessionBalanceLabel = sessionBalanceLabel;
        } else {
            throw new Error('No element matching id session-balance found');
        }

        this.initialiseDisplay();
        
        this.onGameBegin(this.onDataResponse, this);
        this.onGameComplete(this.onGameEnd, this);
        this.onJackpot(this.onJackpotWin, this);
    },
    methods: {
        orientationChange(orientation: OrientationValue): void {
            const sessionDiv = document.getElementById('session-data');
            if (sessionDiv) {
                sessionDiv.style.justifyContent = labelJustifications[this.labelJustification[orientation] as keyof typeof labelJustifications];
            }
        },
        initialiseDisplay(): void {
            this.$emit('SessionDataOverlaysGame', true);
            this.inActivityResetEnabled = true;
            this.updateTimerDisplay('--:--:--');
            this.updateBalanceDisplay(0);
        },
        onDataResponse(response: ServerSessionResponse): void {
            // Resumes currently happen before this is mounted,
            // this future proofs incase that ever changes unintentionally
            if (response.RequestType === 'Resume') { return; }
            if (response.SessionData === undefined) { return; }

            this.parseSessionData(response.SessionData);
            this.resetActivityTracker();
            if (this.sessionTimeStart === -1) {
                this.startSessionTimer();
            }
            this.updateBalanceDisplay(this.sessionModel.gameStart.sessionBalance);
        },
        onGameEnd(): void {
            this.updateBalanceDisplay(this.sessionModel.gameEnd.sessionBalance);
        },
        onJackpotWin(amount: number) : void {
            this.updateBalanceDisplay(this.displayedBalance + amount);
        },
        parseSessionData(data: SessionData): void {
            this.sessionModel = {
                totalSpend: 0,
                gameStart: {
                    totalWin: 0,
                    sessionBalance: data.StartProfit
                },
                gameEnd: {
                    totalWin: 0,
                    sessionBalance: data.EndProfit
                }
            };
        },
        updateBalanceDisplay(val: number): void {
            this.displayedBalance = val;
            this.sessionBalanceLabel.innerText = `${this.strings.balanceLabel}: ${this.formatBalance(val)}`;
        },
        updateTimerDisplay(time: string): void {
            this.sessionTimeLabel.innerText = `${this.strings.timeLabel}: ${time}`;
        },
        updateGameNameDisplay(gameId: number = 0): void {
            if (gameId !== 0) {
                this.sessionTimeLabel.innerText = `${this.displayName} : ${gameId.toString()}`;
            } else {
                this.sessionTimeLabel.innerText = `${this.displayName}`;
            }
        },
        startSessionTimer(): void {
            this.localActivityTime = this.sessionTimeStart = new Date().getTime();
            this.sessionTimeTick();
            this.clockTickInterval = window.setInterval(() => {
                this.sessionTimeTick();
            }, msPerSecond);
        },
        sessionTimeTick(): void {
            if (this.inActivityResetEnabled && this.localActivityTime / msPerSecond + this.inActiveTimeOutLimit < new Date().getTime() / msPerSecond) {
                // resets session time to 0 after inactivity = inActiveTimeOutLimit
                this.resetSession();
                return;
            }

            const timeDifference: number = (new Date().getTime() - this.sessionTimeStart) / msPerSecond;
            const days = Math.floor(timeDifference / secondsPerDay);
            const hours = Math.floor((timeDifference % secondsPerDay) / secondsPerHour);
            const mins = Math.floor(((timeDifference % secondsPerDay) % secondsPerHour) / 60);
            const secs = Math.floor(((timeDifference % secondsPerDay) % secondsPerHour) % 60);

            const formatedTimer = this.concatTimeToString(days, hours, mins, secs);
            this.updateTimerDisplay(formatedTimer);
        },
        resetActivityTracker(): void {
            this.localActivityTime = new Date().getTime();
        },
        resetSession(): void {
            window.clearInterval(this.clockTickInterval);
            this.sessionTimeStart = -1;
            this.updateTimerDisplay('--:--:--');
            this.sessionBalanceLabel.innerText = `${this.strings.balanceLabel}: ${this.formatBalance(0)}`;
        },
        concatTimeToString(days: number, hours: number, minutes: number, seconds: number): string {
            return `${days > 0 ? `${days.toString()}:` : ''}${this.formatTimeToString(hours)}:${this.formatTimeToString(minutes)}:${this.formatTimeToString(seconds)}`;
        },
        formatTimeToString(time: number): string {
            return time.toString().padStart(2, '0');
        },
        formatBalance(currencyValue: number): string {
            const balance: string = this.formatCurrency(Math.abs(currencyValue), true);
            const finalBalance = currencyValue < 0 ? `-${balance}` : balance;
            return finalBalance;
        }
    }
});